const ROSTER=[{"key":"zeus","nome":"Zeus","faccao":"Grega","elem":"Tempestade","classe":"Mágico","funcao":"Atacante","inicial":true},{"key":"hades","nome":"Hades","faccao":"Grega","elem":"Umbra","classe":"Mágico","funcao":"Controlador","inicial":false,"prov":{"nome":"O Portão Não Se Abre","nivel":"Ordália","dif":3,"cond":"Elimine os três em definitivo. Bennu e Nezha renascem; Chang'e não cai abaixo de 1 de HP. Só a execução dos Portões do Submundo e as Correntes do Tártaro resolvem — você tem 3 usos do Milagre em 14 turnos.","req":"Cap. 8"}},{"key":"poseidon","nome":"Poseidon","faccao":"Grega","elem":"Maré","classe":"Mágico","funcao":"Atacante","inicial":false,"prov":{"nome":"A Maré Não Espera","nivel":"Provação","dif":2,"cond":"Vença em 8 turnos. Cada inimigo tem de estar Encharcado no momento em que cai — se algum morrer seco, a Provação falha.","req":"—"}},{"key":"atena","nome":"Atena","faccao":"Grega","elem":"Aurora","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"Nenhum Escudo Cai","nivel":"Ordália","dif":3,"cond":"Vença sem perder um aliado, contra o time desenhado para anular a Égide: Ogum destrói Defesa Destrutível, Aquiles causa dano puro, o dano de Tyr não pode ser reduzido nem absorvido. Você não pode usar o Milagre.","req":"Possuir 12 deuses"}},{"key":"ares","nome":"Ares","faccao":"Grega","elem":"Chama","classe":"Físico","funcao":"Atacante","inicial":false,"prov":{"nome":"Sangue por Sangue","nivel":"Rito","dif":1,"cond":"Vença com Ares abaixo de 30 de HP no golpe final. Curar Ares acima de 60 anula a Provação — ele precisa apanhar para bater.","req":"—"}},{"key":"apolo","nome":"Apolo","faccao":"Grega","elem":"Aurora","classe":"Mágico","funcao":"Atacante","inicial":false,"prov":{"nome":"A Aurora Não Erra","nivel":"Provação","dif":2,"cond":"Vença em 10 turnos sem perder um aliado. Apolo é o único curandeiro e você não pode usar o Milagre dele — só a Canção da Cura, recarga 2, contra três fontes de DoT.","req":"—"}},{"key":"afrodite","nome":"Afrodite","faccao":"Grega","elem":"Aurora","classe":"Mágico","funcao":"Controlador","inicial":false,"prov":{"nome":"Que Se Matem","nivel":"Ordália","dif":3,"cond":"Pelo menos dois dos três inimigos têm de ser derrotados por aliados deles, via Encanto ou Paixão Fatal. Abate feito pelo seu time não conta para esses dois.","req":"Cap. 6"}},{"key":"hera","nome":"Hera","faccao":"Grega","elem":"Tempestade","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"O Juramento","nivel":"Provação","dif":2,"cond":"Vença sem perder um aliado, e o Juramento Nupcial tem de estar ativo no turno em que o último inimigo cai.","req":"—"}},{"key":"demeter","nome":"Deméter","faccao":"Grega","elem":"Verdejante","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"A Colheita Retorna","nivel":"Provação","dif":2,"cond":"Você começa com dois aliados já caídos. Traga os dois de volta e vença — mas Ammit impede revive de quem ela matou, Anúbis sela e Hel marca. Você tem de limpar as marcas antes de reviver.","req":"—"}},{"key":"dionisio","nome":"Dionísio","faccao":"Grega","elem":"Verdejante","classe":"Mágico","funcao":"Controlador","inicial":false,"prov":{"nome":"O Banquete","nivel":"Provação","dif":2,"cond":"Vença sem que nenhum inimigo consiga usar um único Milagre em 12 turnos. Silêncio, Bacanal e o passivo de negação de orbe são as únicas ferramentas.","req":"—"}},{"key":"hermes","nome":"Hermes","faccao":"Grega","elem":"Tempestade","classe":"Físico","funcao":"Manipulador","inicial":false,"prov":{"nome":"Roubo Perfeito","nivel":"Ordália","dif":3,"cond":"Você começa com 0 orbes e não recebe geração nenhuma na partida — só pode gastar orbe roubado. E Heimdall bloqueia roubo enquanto vive, então ele tem de cair primeiro, com o Básico.","req":"Possuir 20 deuses"}},{"key":"hercules","nome":"Hércules","faccao":"Grega","elem":"Chama","classe":"Físico","funcao":"Guardião","inicial":false,"prov":{"nome":"Os Doze Trabalhos","nivel":"Provação","dif":2,"cond":"O golpe final tem de ser Os Doze Trabalhos com no mínimo 5 acúmulos (+20 de dano). Usar o Milagre em qualquer momento anula a Provação — a paciência é o teste.","req":"—"}},{"key":"aquiles","nome":"Aquiles","faccao":"Grega","elem":"Chama","classe":"Físico","funcao":"Atacante","inicial":false,"prov":{"nome":"O Calcanhar","nivel":"Provação","dif":2,"cond":"Vença sem que Aquiles caia abaixo de 40 de HP, contra o único tipo de unidade que fura a passiva dele.","req":"—"}},{"key":"perseu","nome":"Perseu","faccao":"Grega","elem":"Aurora","classe":"Físico","funcao":"Atacante","inicial":false,"prov":{"nome":"O Espelho","nivel":"Provação","dif":2,"cond":"Vença em 10 turnos sem que nenhum aliado seja atordoado, selado ou petrificado uma única vez.","req":"—"}},{"key":"orfeu","nome":"Orfeu","faccao":"Grega","elem":"Umbra","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"A Canção Desce","nivel":"Provação","dif":2,"cond":"A partir do turno 3, tem de haver sempre pelo menos um inimigo Adormecido no fim do seu turno. Um turno sem ninguém dormindo anula a Provação.","req":"—"}},{"key":"medusa","nome":"Medusa","faccao":"Grega","elem":"Umbra","classe":"Mágico","funcao":"Controlador","inicial":false,"prov":{"nome":"Três Marcas","nivel":"Ordália","dif":3,"cond":"Os três inimigos têm de estar Petrificados ao mesmo tempo em algum momento. Perseu é imune e devolve a petrificação a quem tentar — ele tem de cair antes.","req":"Cap. 4"}},{"key":"cerberus","nome":"Cérberus","faccao":"Grega","elem":"Umbra","classe":"Físico","funcao":"Guardião","inicial":false,"prov":{"nome":"Ninguém Passa","nivel":"Provação","dif":2,"cond":"Nenhum aliado além de Cérberus pode sofrer dano em toda a partida. Fenrir e Kali são imunes a Provocar quando escalados — você tem de interceptar de outro jeito.","req":"—"}},{"key":"erinias","nome":"Erínias","faccao":"Grega","elem":"Umbra","classe":"Mágico","funcao":"Controlador","inicial":false,"prov":{"nome":"Vingança Cobrada","nivel":"Provação","dif":2,"cond":"Você começa com um aliado caído. Vença com Erínias como única sobrevivente — se o terceiro aliado estiver vivo no fim, a Provação falha.","req":"—"}},{"key":"kraken","nome":"Kraken","faccao":"Grega","elem":"Maré","classe":"Físico","funcao":"Guardião","inicial":false,"prov":{"nome":"O Abismo Reclama","nivel":"Rito","dif":1,"cond":"Vença em 7 turnos, e a Fúria do Abismo tem de ser o golpe final de pelo menos dois inimigos.","req":"—"}},{"key":"odin","nome":"Odin","faccao":"Nórdica","elem":"Umbra","classe":"Híbrido","funcao":"Suporte","inicial":false,"prov":{"nome":"O Preço do Olho","nivel":"Ordália","dif":3,"cond":"Odin tem de terminar a partida com 40 de HP ou menos — a Sabedoria do Enforcado precisa ser usada no mínimo 3 vezes. Curar Odin anula a Provação.","req":"Possuir 2 deuses Nórdicos"}},{"key":"thor","nome":"Thor","faccao":"Nórdica","elem":"Tempestade","classe":"Físico","funcao":"Guardião","inicial":false,"prov":{"nome":"O Trovão de Asgard","nivel":"Provação","dif":2,"cond":"Vença sem perder um aliado. A passiva de Thor não protege contra dano puro, e os três inimigos só causam dano puro — a proteção tem de vir de posicionamento e abate rápido.","req":"—"}},{"key":"loki","nome":"Loki","faccao":"Nórdica","elem":"Umbra","classe":"Mágico","funcao":"Manipulador","inicial":false,"prov":{"nome":"Trama Completa","nivel":"Ordália","dif":3,"cond":"A Trama do Caos tem de roubar no mínimo 6 buffs de uma só vez. O time inimigo aplica buffs todo turno; você tem de escolher o turno exato e sobreviver até lá sem gastar o Milagre.","req":"Cap. 11"}},{"key":"fenrir","nome":"Fenrir","faccao":"Nórdica","elem":"Umbra","classe":"Físico","funcao":"Atacante","inicial":false,"prov":{"nome":"Fauces do Fim","nivel":"Provação","dif":2,"cond":"Todos os três inimigos têm de cair por execução das Fauces do Fim. Enquanto Chang'e, Vishnu ou Oxalá estiverem ativos, ninguém cai abaixo de 1 de HP — a ordem de abate é o enigma.","req":"—"}},{"key":"hel","nome":"Hel","faccao":"Nórdica","elem":"Umbra","classe":"Mágico","funcao":"Controlador","inicial":false,"prov":{"nome":"Metade de Cada","nivel":"Provação","dif":2,"cond":"Vença sem que nenhum inimigo seja revivido. A Marca da Morte tem de estar em cada um no turno em que ele cai.","req":"—"}},{"key":"heimdall","nome":"Heimdall","faccao":"Nórdica","elem":"Aurora","classe":"Físico","funcao":"Guardião","inicial":false,"prov":{"nome":"A Vigília Não Dorme","nivel":"Provação","dif":2,"cond":"Vença em 12 turnos sem perder um único orbe para o inimigo. A passiva bloqueia roubo — mas se Heimdall cair, a proteção cai com ele, e os três vão focá-lo.","req":"—"}},{"key":"freyja","nome":"Freyja","faccao":"Nórdica","elem":"Aurora","classe":"Híbrido","funcao":"Suporte","inicial":false,"prov":{"nome":"O Salão dos Caídos","nivel":"Provação","dif":2,"cond":"Um aliado tem de cair e voltar pelo Salão dos Caídos, e você tem de vencer com os três vivos. Cérberus impede revive enquanto vive; Ammit impede permanentemente quem ela mata.","req":"—"}},{"key":"tyr","nome":"Tyr","faccao":"Nórdica","elem":"Aurora","classe":"Físico","funcao":"Guardião","inicial":true},{"key":"baldur","nome":"Baldur","faccao":"Nórdica","elem":"Aurora","classe":"Mágico","funcao":"Guardião","inicial":false,"prov":{"nome":"O Visco","nivel":"Rito","dif":1,"cond":"Vença contra a única fraqueza de Baldur. A passiva não reduz dano Verdejante, e os três inimigos são exatamente isso.","req":"—"}},{"key":"bragi","nome":"Bragi","faccao":"Nórdica","elem":"Aurora","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"A Saga","nivel":"Rito","dif":1,"cond":"Vença em 9 turnos. Bragi não pode usar o Básico em nenhum turno — só Saga Heroica e a Canção de Valhalla. O dano tem de sair dos aliados que ele buffa.","req":"—"}},{"key":"mimir","nome":"Mimir","faccao":"Nórdica","elem":"Umbra","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"A Cabeça Falante","nivel":"Provação","dif":2,"cond":"Mimir tem de estar morto quando o último inimigo cair, e o time tem de vencer com o bônus da passiva dele. Reviver Mimir anula a Provação.","req":"Possuir Odin"}},{"key":"ymir","nome":"Ymir","faccao":"Nórdica","elem":"Maré","classe":"Físico","funcao":"Guardião","inicial":false,"prov":{"nome":"Carne Primordial","nivel":"Rito","dif":1,"cond":"Ymir tem de cair e a cura da passiva dele tem de ser o que mantém o time vivo — vença com os outros dois aliados abaixo de 30 de HP.","req":"—"}},{"key":"jormungandr","nome":"Jörmungandr","faccao":"Nórdica","elem":"Maré","classe":"Mágico","funcao":"Atacante","inicial":false,"prov":{"nome":"O Anel se Fecha","nivel":"Provação","dif":2,"cond":"Os três inimigos têm de morrer de Veneno, não de golpe direto. Um abate por dano de habilidade anula a Provação.","req":"—"}},{"key":"ra","nome":"Rá","faccao":"Egípcia","elem":"Aurora","classe":"Mágico","funcao":"Atacante","inicial":false,"prov":{"nome":"Seis Discos","nivel":"Provação","dif":2,"cond":"O Olho de Rá tem de ser disparado com 6 Discos Solares acumulados. Hou Yi vai tentar te matar antes — você tem no mínimo 6 turnos de sobrevivência a cumprir.","req":"—"}},{"key":"osiris","nome":"Osíris","faccao":"Egípcia","elem":"Umbra","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"O Tribunal","nivel":"Ordália","dif":3,"cond":"Dois aliados têm de cair e voltar pelo Tribunal do Duat, e você tem de vencer com os três vivos — contra o time que existe justamente para impedir isso.","req":"Cap. 9"}},{"key":"isis","nome":"Ísis","faccao":"Egípcia","elem":"Aurora","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"O Nome Secreto","nivel":"Ordália","dif":3,"cond":"Os três aliados têm de estar caídos ao mesmo tempo, e a Ressurreição de Osíris tem de trazer todos de volta em um único uso — depois vença. Cérberus bloqueia revive enquanto vive.","req":"Possuir 15 deuses"}},{"key":"horus","nome":"Hórus","faccao":"Egípcia","elem":"Tempestade","classe":"Físico","funcao":"Atacante","inicial":false,"prov":{"nome":"O Olho Vê","nivel":"Provação","dif":2,"cond":"Todos os três inimigos têm de cair pelo Mergulho do Falcão com o Olho aplicado (dano puro dobrado). O Básico de Hórus ignora Inalvejável — é a única via de aplicar o Olho.","req":"—"}},{"key":"anubis","nome":"Anúbis","faccao":"Egípcia","elem":"Umbra","classe":"Mágico","funcao":"Controlador","inicial":false,"prov":{"nome":"A Pesagem","nivel":"Ordália","dif":3,"cond":"Os três inimigos têm de chegar a 4 Ataduras e ficar Selados ao mesmo tempo. O time inimigo remove debuff a cada turno — você tem de aplicar mais rápido do que eles limpam.","req":"Cap. 5"}},{"key":"bastet","nome":"Bastet","faccao":"Egípcia","elem":"Aurora","classe":"Físico","funcao":"Guardião","inicial":false,"prov":{"nome":"Sete Vidas","nivel":"Provação","dif":2,"cond":"Nenhum aliado além de Bastet pode sofrer dano de alvo único em toda a partida. Vigília da Gata tem recarga 2 e os inimigos atacam três vezes por turno.","req":"—"}},{"key":"sobek","nome":"Sobek","faccao":"Egípcia","elem":"Maré","classe":"Físico","funcao":"Guardião","inicial":true},{"key":"ammit","nome":"Ammit","faccao":"Egípcia","elem":"Umbra","classe":"Físico","funcao":"Atacante","inicial":false,"prov":{"nome":"Devorar a Alma","nivel":"Provação","dif":2,"cond":"Os três têm de cair pela execução do Devorar a Alma. Contra três fontes de imunidade, você tem de sincronizar os selos e as janelas.","req":"—"}},{"key":"bennu","nome":"Bennu","faccao":"Egípcia","elem":"Chama","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"Das Cinzas","nivel":"Rito","dif":1,"cond":"Bennu tem de morrer e renascer pela passiva, e vencer depois disso. Terminar a partida sem Bennu ter caído anula a Provação.","req":"—"}},{"key":"khnum","nome":"Khnum","faccao":"Egípcia","elem":"Verdejante","classe":"Mágico","funcao":"Manipulador","inicial":false,"prov":{"nome":"O Torno","nivel":"Provação","dif":2,"cond":"A Couraça de Barro tem de absorver no mínimo 60 de dano acumulado. Iansã remove buffs com a Ventania — você tem de remoldar e proteger.","req":"—"}},{"key":"khonshu","nome":"Khonshu","faccao":"Egípcia","elem":"Umbra","classe":"Mágico","funcao":"Manipulador","inicial":false,"prov":{"nome":"A Passagem do Tempo","nivel":"Provação","dif":2,"cond":"Vença sem que nenhum inimigo consiga usar o Milagre. O time inimigo inteiro reduz recarga todo turno; você só tem a Passagem do Tempo, recarga 2.","req":"—"}},{"key":"babi","nome":"Babi","faccao":"Egípcia","elem":"Umbra","classe":"Físico","funcao":"Atacante","inicial":false,"prov":{"nome":"O Rugido","nivel":"Rito","dif":1,"cond":"Vença contra três unidades imunes ao seu controle principal. O Frenesi Sanguinário e a passiva de Medo ficam inúteis — o teste é achar dano sem eles.","req":"—"}},{"key":"nefertem","nome":"Nefertem","faccao":"Egípcia","elem":"Verdejante","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"O Perfume","nivel":"Rito","dif":1,"cond":"Vença em 10 turnos sem que nenhum aliado termine um turno com qualquer debuff ativo. Perfume de Lótus tem recarga 1 — mas há três fontes de debuff.","req":"—"}},{"key":"mnevis","nome":"Mnevis","faccao":"Egípcia","elem":"Aurora","classe":"Físico","funcao":"Guardião","inicial":false,"prov":{"nome":"A Montaria do Sol","nivel":"Provação","dif":2,"cond":"Rá tem de sobreviver com HP cheio até o fim. Qualquer dano que chegue nele anula a Provação — a passiva de intercepção só cobre o primeiro ataque de cada turno.","req":"Possuir Rá"}},{"key":"amaterasu","nome":"Amaterasu","faccao":"Japonesa","elem":"Aurora","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"O Sol Não Se Põe","nivel":"Provação","dif":2,"cond":"O DIA tem de estar ativo em todos os turnos a partir do turno 2. Um único turno de Noite ou de campo neutro anula a Provação.","req":"—"}},{"key":"susanoo","nome":"Susanoo","faccao":"Japonesa","elem":"Tempestade","classe":"Híbrido","funcao":"Atacante","inicial":false,"prov":{"nome":"Oito Cabeças","nivel":"Ordália","dif":3,"cond":"A Fúria do Tufão tem de ser disparada com 20 de Combo (o teto) e derrubar dois inimigos no mesmo golpe. Os escudos inimigos crescem todo turno.","req":"Cap. 10"}},{"key":"tsukuyomi","nome":"Tsukuyomi","faccao":"Japonesa","elem":"Umbra","classe":"Mágico","funcao":"Controlador","inicial":false,"prov":{"nome":"A Lua Julga","nivel":"Provação","dif":2,"cond":"Vença com a NOITE ativa em todos os turnos a partir do turno 2, contra o time que a desfaz.","req":"—"}},{"key":"izanami","nome":"Izanami","faccao":"Japonesa","elem":"Umbra","classe":"Mágico","funcao":"Controlador","inicial":false,"prov":{"nome":"Mil por Dia","nivel":"Ordália","dif":3,"cond":"Os três inimigos têm de morrer pela execução do Portal de Yomotsu, amaldiçoados. Izanagi imuniza o time inteiro contra Maldição — ele tem de cair primeiro, e ele é o mais protegido.","req":"Cap. 10"}},{"key":"izanagi","nome":"Izanagi","faccao":"Japonesa","elem":"Verdejante","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"Misogi","nivel":"Provação","dif":2,"cond":"Vença em 12 turnos sem que nenhum aliado morra de DoT. O dano direto do time inimigo é baixo — a partida inteira é gestão de limpeza.","req":"Possuir Izanami"}},{"key":"raijin","nome":"Raijin","faccao":"Japonesa","elem":"Tempestade","classe":"Mágico","funcao":"Atacante","inicial":false,"prov":{"nome":"O Ritmo","nivel":"Rito","dif":1,"cond":"Vença em 8 turnos gerando no mínimo 15 de Combo. O Raio em Cadeia tem de acertar os três inimigos em pelo menos 3 turnos distintos.","req":"—"}},{"key":"fujin","nome":"Fujin","faccao":"Japonesa","elem":"Tempestade","classe":"Mágico","funcao":"Manipulador","inicial":true},{"key":"inari","nome":"Inari","faccao":"Japonesa","elem":"Verdejante","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"As Mil Portas","nivel":"Rito","dif":1,"cond":"Termine a partida com 8 ou mais orbes guardados. O time inimigo rouba e remove orbe todo turno — Inari tem de gerar mais rápido do que eles drenam.","req":"—"}},{"key":"kagutsuchi","nome":"Kagutsuchi","faccao":"Japonesa","elem":"Chama","classe":"Mágico","funcao":"Atacante","inicial":false,"prov":{"nome":"A Chama que Consome","nivel":"Provação","dif":2,"cond":"Vença contra três unidades imunes ao seu único eixo de dano. A passiva ainda tira 3 de HP seu por turno — o relógio corre contra você.","req":"—"}},{"key":"kitsune","nome":"Kitsune","faccao":"Japonesa","elem":"Umbra","classe":"Mágico","funcao":"Manipulador","inicial":false,"prov":{"nome":"Nove Caudas","nivel":"Provação","dif":2,"cond":"Nove Caudas tem de ser disparado com as 9 Caudas. Isso exige sobreviver 18 turnos contra um time que destrói suas miragens — e o empate técnico é no turno 40, então há margem, mas pouca.","req":"Possuir Inari"}},{"key":"tanuki","nome":"Tanuki","faccao":"Japonesa","elem":"Verdejante","classe":"Mágico","funcao":"Manipulador","inicial":false,"prov":{"nome":"A Sorte Não Existe","nivel":"Rito","dif":1,"cond":"Vença sem repetir a mesma escolha da Metamorfose duas vezes consecutivas, e sem usar o Golpe da Sorte.","req":"—"}},{"key":"oni","nome":"Oni","faccao":"Japonesa","elem":"Chama","classe":"Físico","funcao":"Guardião","inicial":false,"prov":{"nome":"Pele Grossa","nivel":"Rito","dif":1,"cond":"Vença sem perder um aliado. A passiva de Oni não serve contra nenhum dos três — o Provocar tem de ser usado como recurso de tempo, não de proteção.","req":"—"}},{"key":"shutendoji","nome":"Shuten Dōji","faccao":"Japonesa","elem":"Umbra","classe":"Físico","funcao":"Guardião","inicial":false,"prov":{"nome":"O Banquete de Ōe","nivel":"Provação","dif":2,"cond":"Roube no mínimo 8 orbes com o Torpor em 12 turnos, e vença. Se o inimigo usar dois Milagres, a Provação falha.","req":"—"}},{"key":"yamatotakeru","nome":"Yamato Takeru","faccao":"Japonesa","elem":"Tempestade","classe":"Físico","funcao":"Atacante","inicial":false,"prov":{"nome":"Ceifa-Ervas","nivel":"Provação","dif":2,"cond":"O golpe final tem de ser o Corte Ceifa-Ervas com 20 de Combo, e ele tem de remover no mínimo 3 buffs do alvo no processo.","req":"—"}},{"key":"sunwukong","nome":"Sun Wukong","faccao":"Chinesa","elem":"Verdejante","classe":"Físico","funcao":"Atacante","inicial":false,"prov":{"nome":"Setenta e Duas","nivel":"Provação","dif":2,"cond":"Vença sem que Wukong use a passiva de sobrevivência (não pode ser reduzido a 1 de HP nenhuma vez). Os três inimigos existem para executar — e a passiva contra execução é a sua rede.","req":"—"}},{"key":"nuwa","nome":"Nüwa","faccao":"Chinesa","elem":"Aurora","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"Remendar o Céu","nivel":"Ordália","dif":3,"cond":"Vença sem perder um aliado. Cada uso das Pedras das Cinco Cores tem de escolher um par diferente do anterior — você não pode repetir a mesma combinação duas vezes.","req":"Possuir 18 deuses"}},{"key":"huangdi","nome":"Huang Di","faccao":"Chinesa","elem":"Aurora","classe":"Híbrido","funcao":"Suporte","inicial":false,"prov":{"nome":"A Ordem Imperial","nivel":"Provação","dif":2,"cond":"Vença em 10 turnos. Nenhuma habilidade aliada pode ficar mais de 1 turno em recarga em nenhum momento — o time inimigo existe para atrasar você.","req":"—"}},{"key":"aokuang","nome":"Ao Kuang","faccao":"Chinesa","elem":"Maré","classe":"Mágico","funcao":"Controlador","inicial":false,"prov":{"nome":"A Chuva Cai","nivel":"Rito","dif":1,"cond":"Os três inimigos têm de estar Encharcados e atordoados ao mesmo tempo em algum momento, e você tem de vencer nos 2 turnos seguintes.","req":"—"}},{"key":"nezha","nome":"Nezha","faccao":"Chinesa","elem":"Chama","classe":"Híbrido","funcao":"Atacante","inicial":true},{"key":"guanyu","nome":"Guan Yu","faccao":"Chinesa","elem":"Verdejante","classe":"Físico","funcao":"Guardião","inicial":false,"prov":{"nome":"O Juramento do Pêssego","nivel":"Rito","dif":1,"cond":"Vença com os três aliados vivos. A imunidade a Medo da passiva só existe com o time completo — perder um aliado quebra a imunidade e provavelmente a partida.","req":"—"}},{"key":"houyi","nome":"Hou Yi","faccao":"Chinesa","elem":"Chama","classe":"Físico","funcao":"Atacante","inicial":false,"prov":{"nome":"Abater o Sol","nivel":"Provação","dif":2,"cond":"O DIA tem de ser removido no mínimo 3 vezes, e você tem de vencer sem usar o Milagre. Amaterasu reativa o Dia com recarga 2.","req":"—"}},{"key":"yanwong","nome":"Yan Wong","faccao":"Chinesa","elem":"Umbra","classe":"Mágico","funcao":"Controlador","inicial":false,"prov":{"nome":"O Livro","nivel":"Provação","dif":2,"cond":"Os três inimigos têm de morrer pela contagem do Livro da Vida e Morte, nunca por dano. O time inimigo limpa a inscrição — você tem de inscrever mais rápido do que eles removem.","req":"—"}},{"key":"change","nome":"Chang'e","faccao":"Chinesa","elem":"Umbra","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"Saudade","nivel":"Rito","dif":1,"cond":"Vença sem que nenhum aliado caia. Hou Yi tem de estar no seu time — a sinergia da passiva é o que torna o Elixir sustentável.","req":"Possuir Hou Yi"}},{"key":"shiva","nome":"Shiva","faccao":"Hindu","elem":"Umbra","classe":"Mágico","funcao":"Atacante","inicial":false,"prov":{"nome":"O Terceiro Olho","nivel":"Ordália","dif":3,"cond":"Vença SEM usar o Terceiro Olho uma única vez. A Provação do deus mais destrutivo do jogo é provar que você não precisa dele — Tandava acumulando é o caminho, e leva tempo.","req":"Cap. 5"}},{"key":"vishnu","nome":"Vishnu","faccao":"Hindu","elem":"Aurora","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"Preservar","nivel":"Ordália","dif":3,"cond":"Vença com os três aliados em HP cheio (100) no golpe final. Contra três fontes de dano que ignoram defesa, isso exige usar a Encarnação e a cura do Milagre em sincronia perfeita.","req":"Possuir 18 deuses"}},{"key":"krishna","nome":"Krishna","faccao":"Hindu","elem":"Aurora","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"A Ação Perfeita","nivel":"Provação","dif":2,"cond":"Todo golpe que derruba um inimigo tem de ser feito sob Ação Perfeita. Um abate sem o buff ativo anula a Provação — e a recarga é 2.","req":"—"}},{"key":"kali","nome":"Kali","faccao":"Hindu","elem":"Umbra","classe":"Físico","funcao":"Atacante","inicial":false,"prov":{"nome":"A Dança","nivel":"Provação","dif":2,"cond":"Vença em 9 turnos. Kali não pode ser curada em nenhum momento — nem pelo Frenesi, nem por aliado. A Guirlanda de Caveiras é a única cura permitida.","req":"—"}},{"key":"brahma","nome":"Brahma","faccao":"Hindu","elem":"Verdejante","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"Quatro Faces","nivel":"Provação","dif":2,"cond":"O time tem de terminar a partida com +20 de dano acumulado pelas Quatro Faces (5 usos). O time inimigo remove buff todo turno — mas o bônus das Quatro Faces é permanente, e essa é a lição.","req":"—"}},{"key":"durga","nome":"Durga","faccao":"Hindu","elem":"Chama","classe":"Físico","funcao":"Atacante","inicial":false,"prov":{"nome":"Mahishasura","nivel":"Rito","dif":1,"cond":"Todos os três inimigos têm de cair pelo Fim de Mahishasura acima de 70 de HP (dano de 48). Deixar um cair abaixo de 70 anula a Provação.","req":"—"}},{"key":"hanuman","nome":"Hanuman","faccao":"Hindu","elem":"Tempestade","classe":"Físico","funcao":"Guardião","inicial":false,"prov":{"nome":"Devoção a Rama","nivel":"Provação","dif":2,"cond":"O Senhor adotado tem de sobreviver a partida inteira sem sofrer um único ponto de dano. Sun Wukong tem de estar no seu time.","req":"Possuir Sun Wukong"}},{"key":"ganesha","nome":"Ganesha","faccao":"Hindu","elem":"Verdejante","classe":"Mágico","funcao":"Suporte","inicial":true},{"key":"saci","nome":"Saci","faccao":"Brasileira","elem":"Tempestade","classe":"Físico","funcao":"Manipulador","inicial":false,"prov":{"nome":"A Travessura","nivel":"Rito","dif":1,"cond":"Vença em 9 turnos roubando no mínimo 5 orbes e 3 buffs. Os três inimigos furam a passiva do Gorro Vermelho — ela não vai te salvar.","req":"—"}},{"key":"boitata","nome":"Boitatá","faccao":"Brasileira","elem":"Chama","classe":"Mágico","funcao":"Guardião","inicial":false,"prov":{"nome":"Guardiã dos Campos","nivel":"Rito","dif":1,"cond":"Vença sem que nenhum aliado além de Boitatá sofra dano de Queimadura. A passiva converte fogo em cura — o teste é atrair o fogo para ela.","req":"—"}},{"key":"iara","nome":"Iara","faccao":"Brasileira","elem":"Maré","classe":"Mágico","funcao":"Controlador","inicial":false,"prov":{"nome":"O Canto","nivel":"Provação","dif":2,"cond":"Os três inimigos têm de morrer Encharcados, e no mínimo dois pela execução do Afogamento. Fenrir é imune a Provocar; Tyr fura o silêncio com o Básico.","req":"—"}},{"key":"curupira","nome":"Curupira","faccao":"Brasileira","elem":"Verdejante","classe":"Físico","funcao":"Controlador","inicial":false,"prov":{"nome":"Pés Virados","nivel":"Provação","dif":2,"cond":"Dois dos três inimigos têm de ser derrotados por aliados deles, sob o efeito de Pés Virados.","req":"—"}},{"key":"cuca","nome":"Cuca","faccao":"Brasileira","elem":"Umbra","classe":"Mágico","funcao":"Controlador","inicial":true},{"key":"mulasemcabeca","nome":"Mula sem Cabeça","faccao":"Brasileira","elem":"Chama","classe":"Físico","funcao":"Atacante","inicial":false,"prov":{"nome":"Quinta-feira","nivel":"Rito","dif":1,"cond":"Vença com a Mula abaixo de 25 de HP no golpe final. Ela só é imune a controle durante o Galope — fora dele, os três vão travá-la.","req":"—"}},{"key":"boto","nome":"Boto","faccao":"Brasileira","elem":"Maré","classe":"Mágico","funcao":"Manipulador","inicial":false,"prov":{"nome":"Festa de São João","nivel":"Provação","dif":2,"cond":"Vença sem que nenhum inimigo use um Milagre em 12 turnos. Festa de São João tem recarga 4 e cobre 2 turnos — a conta não fecha sozinha, você tem de somar Dominação.","req":"—"}},{"key":"piranha","nome":"Piranha","faccao":"Brasileira","elem":"Maré","classe":"Físico","funcao":"Atacante","inicial":false,"prov":{"nome":"Águas Vermelhas","nivel":"Rito","dif":1,"cond":"Os três inimigos têm de morrer de Sangramento, nunca de golpe direto. Sangramento é dano puro — é o único caminho que atravessa aquele time, e essa é a lição.","req":"—"}},{"key":"exu","nome":"Exu","faccao":"Africana","elem":"Umbra","classe":"Mágico","funcao":"Manipulador","inicial":false,"prov":{"nome":"A Encruzilhada","nivel":"Ordália","dif":3,"cond":"Vença em 10 turnos tendo usado no mínimo 6 vezes o Fechar Caminhos, e sem que nenhum inimigo use o Milagre. Heimdall anula seu roubo enquanto vive.","req":"Cap. 9"}},{"key":"xango","nome":"Xangô","faccao":"Africana","elem":"Chama","classe":"Híbrido","funcao":"Atacante","inicial":false,"prov":{"nome":"A Balança","nivel":"Ordália","dif":3,"cond":"A Balança da Justiça tem de devolver o máximo (50) de uma só vez, e esse golpe tem de derrubar um inimigo. Você tem de deixar o time apanhar 50 de propósito, sem perder ninguém.","req":"Cap. 9"}},{"key":"oxala","nome":"Oxalá","faccao":"Africana","elem":"Aurora","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"O Mais Velho","nivel":"Provação","dif":2,"cond":"Vença sem perder um aliado e sem causar dano com o Opaxorô em nenhum turno. A Paz de Oxalá e o Manto Branco são as únicas ferramentas — o dano tem de vir dos aliados.","req":"—"}},{"key":"ogum","nome":"Ogum","faccao":"Africana","elem":"Verdejante","classe":"Físico","funcao":"Atacante","inicial":true},{"key":"oxum","nome":"Oxum","faccao":"Africana","elem":"Maré","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"Águas Doces","nivel":"Rito","dif":1,"cond":"Cure no mínimo 120 de HP acumulado e vença. Os três inimigos aplicam 'não pode ser curado' — você tem de limpar ou escolher outro alvo.","req":"—"}},{"key":"iansa","nome":"Iansã","faccao":"Africana","elem":"Tempestade","classe":"Híbrido","funcao":"Controlador","inicial":false,"prov":{"nome":"O Corisco","nivel":"Rito","dif":1,"cond":"Vença removendo todo buff dos três inimigos antes de derrubar qualquer deus.","req":"—"}},{"key":"dagda","nome":"Dagda","faccao":"Celta","elem":"Verdejante","classe":"Híbrido","funcao":"Suporte","inicial":false,"prov":{"nome":"O Caldeirão","nivel":"Provação","dif":2,"cond":"O Caldeirão tem de estar ativo em todos os turnos a partir do turno 3, e você tem de vencer sem perder um aliado. Recarga 3, duração 3 — a conta é exata e não perdoa um turno perdido.","req":"Cap. 12"}},{"key":"lugh","nome":"Lugh","faccao":"Celta","elem":"Aurora","classe":"Híbrido","funcao":"Atacante","inicial":false,"prov":{"nome":"Samildánach","nivel":"Provação","dif":2,"cond":"Vença usando as três modalidades de Samildánach no mínimo 3 vezes cada, com o DIA ativo no golpe final. Tsukuyomi vai forçar a Noite todo turno.","req":"—"}},{"key":"morrigan","nome":"Morrigan","faccao":"Celta","elem":"Umbra","classe":"Mágico","funcao":"Controlador","inicial":false,"prov":{"nome":"As Três Irmãs","nivel":"Provação","dif":2,"cond":"Os três inimigos têm de morrer pela execução do Presságio de Morte, e nenhum pode voltar. Bennu e Nezha renascem pela passiva — o Presságio bloqueia cura, não revive.","req":"—"}},{"key":"brigid","nome":"Brigid","faccao":"Celta","elem":"Chama","classe":"Mágico","funcao":"Suporte","inicial":true},{"key":"cernunnos","nome":"Cernunnos","faccao":"Celta","elem":"Verdejante","classe":"Físico","funcao":"Guardião","inicial":false,"prov":{"nome":"A Matilha","nivel":"Rito","dif":1,"cond":"A Fúria da Matilha tem de refletir no mínimo 50 de dano acumulado, e estar ativa no golpe final.","req":"—"}},{"key":"kukulkan","nome":"Kukulkán","faccao":"Maia","elem":"Tempestade","classe":"Híbrido","funcao":"Atacante","inicial":false,"prov":{"nome":"A Estrela da Manhã","nivel":"Provação","dif":2,"cond":"Vença em 9 turnos. Todo mergulho do Voo da Serpente tem de acertar os três inimigos Encharcados — e você não tem nenhuma unidade Maré no time emprestado, então o Encharcado tem de vir de outro lugar.","req":"Cap. 8"}},{"key":"ahpuch","nome":"Ah Puch","faccao":"Maia","elem":"Umbra","classe":"Mágico","funcao":"Controlador","inicial":false,"prov":{"nome":"A Podridão","nivel":"Ordália","dif":3,"cond":"Cada inimigo tem de cair com no mínimo 4 acúmulos de Podridão (−40 de HP máximo). Itzamná restaura HP máximo perdido com o Milagre — ele tem de cair primeiro, e ele é o mais curado.","req":"Cap. 8"}},{"key":"chaac","nome":"Chaac","faccao":"Maia","elem":"Maré","classe":"Mágico","funcao":"Atacante","inicial":false,"prov":{"nome":"As Quatro Chuvas","nivel":"Rito","dif":1,"cond":"Os três inimigos têm de estar Encharcados e atordoados no mesmo turno, e cair nos 2 turnos seguintes.","req":"—"}},{"key":"itzamna","nome":"Itzamná","faccao":"Maia","elem":"Aurora","classe":"Mágico","funcao":"Suporte","inicial":false,"prov":{"nome":"A Escrita Sagrada","nivel":"Provação","dif":2,"cond":"Vença sem que nenhum aliado termine a partida com HP máximo reduzido, e com no mínimo 4 acúmulos de Escrita Sagrada em um aliado.","req":"—"}}];
